import sys

def simplify_path(path):
    stack = []
    parts = path.split('/')
    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    if not stack:
        return '/'
    return '/' + '/'.join(stack)

def main():
    s = sys.stdin.readline().strip()
    if not s:
        print('/')
        return
    print(simplify_path(s))

if __name__ == "__main__":
    main()
